package com.primehr.learningdevelopment.delivery.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.UUID;
@Entity@Table(name="ld_program",uniqueConstraints={@UniqueConstraint(name="uk_ld_program_series_version",columnNames={"agency_id","series_id","program_version"}),@UniqueConstraint(name="uk_ld_program_code_version",columnNames={"agency_id","normalized_code","program_version"})})
public class LdProgram extends RspAuditedEntity{
 public enum Status{DRAFT,SUBMITTED,APPROVED,CANCELLED}
 @Column(name="series_id",nullable=false,length=36)private String seriesId;@Column(name="program_version",nullable=false)private int programVersion;@Column(name="supersedes_id",length=36)private String supersedesId;@Column(name="plan_id",nullable=false,length=36)private String planId;@Column(name="plan_version",nullable=false)private int planVersion;@Column(name="plan_fingerprint",nullable=false,length=64)private String planFingerprint;@Column(nullable=false,length=80)private String code;@Column(name="normalized_code",nullable=false,length=80)private String normalizedCode;@Column(nullable=false,length=200)private String title;@Column(name="intervention_version_id",nullable=false,length=36)private String interventionVersionId;@Column(name="intervention_fingerprint",nullable=false,length=64)private String interventionFingerprint;@Column(name="evaluation_framework_version_id",nullable=false,length=36)private String evaluationFrameworkVersionId;@Column(name="evaluation_fingerprint",nullable=false,length=64)private String evaluationFingerprint;@Column(name="intended_outcomes",nullable=false,length=4000)private String intendedOutcomes;@Column(name="delivery_strategy",nullable=false,length=4000)private String deliveryStrategy;@Column(name="schedule_start",nullable=false)private LocalDate scheduleStart;@Column(name="schedule_end",nullable=false)private LocalDate scheduleEnd;@Column(name="estimated_hours",nullable=false,precision=9,scale=2)private BigDecimal estimatedHours;@Column(name="estimated_cost",nullable=false,precision=19,scale=2)private BigDecimal estimatedCost;@Column(name="funding_source",nullable=false,length=500)private String fundingSource;@Column(name="accountable_employee_id",nullable=false)private Long accountableEmployeeId;@Column(name="accountable_employee_no",nullable=false,length=100)private String accountableEmployeeNo;@Column(name="accountable_name",nullable=false,length=300)private String accountableName;@Column(name="accountable_appointment_id",nullable=false)private Long accountableAppointmentId;@Column(name="accountable_fingerprint",nullable=false,length=64)private String accountableFingerprint;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="content_revision",nullable=false)private int contentRevision;@Column(name="submitted_by",length=100)private String submittedBy;@Column(name="submitted_at")private Instant submittedAt;@Column(name="approved_by",length=100)private String approvedBy;@Column(name="approved_at")private Instant approvedAt;
 protected LdProgram(){}public LdProgram(String agency,String planId,int planVersion,String planFingerprint,String code,String title,String interventionId,String interventionFingerprint,String evaluationId,String evaluationFingerprint,String outcomes,String strategy,LocalDate start,LocalDate end,BigDecimal hours,BigDecimal cost,String funding,Long employeeId,String employeeNo,String employeeName,Long appointmentId,String employeeFingerprint){super(agency);seriesId=UUID.randomUUID().toString();programVersion=1;this.planId=requiredText(planId,"planId");if(planVersion<1)throw new IllegalArgumentException("planVersion is required");this.planVersion=planVersion;this.planFingerprint=requiredText(planFingerprint,"planFingerprint");this.interventionVersionId=requiredText(interventionId,"interventionVersionId");this.interventionFingerprint=requiredText(interventionFingerprint,"interventionFingerprint");evaluationFrameworkVersionId=requiredText(evaluationId,"evaluationFrameworkVersionId");this.evaluationFingerprint=requiredText(evaluationFingerprint,"evaluationFingerprint");accountableEmployeeId=positive(employeeId,"accountableEmployeeId");accountableEmployeeNo=requiredText(employeeNo,"accountableEmployeeNo");accountableName=requiredText(employeeName,"accountableName");accountableAppointmentId=positive(appointmentId,"accountableAppointmentId");accountableFingerprint=requiredText(employeeFingerprint,"accountableFingerprint");status=Status.DRAFT;contentRevision=1;apply(code,title,outcomes,strategy,start,end,hours,cost,funding);}
 public void update(String code,String title,String outcomes,String strategy,LocalDate start,LocalDate end,BigDecimal hours,BigDecimal cost,String funding){editable();apply(code,title,outcomes,strategy,start,end,hours,cost,funding);contentRevision++;}public void touch(){editable();contentRevision++;}public void submit(String actor,Instant at){editable();status=Status.SUBMITTED;submittedBy=requiredText(actor,"actor");submittedAt=at;}public void approve(String actor,Instant at){if(status!=Status.SUBMITTED)throw new IllegalStateException("Only a SUBMITTED L&D program may be approved");status=Status.APPROVED;approvedBy=requiredText(actor,"actor");approvedAt=at;}public void cancel(){if(status==Status.CANCELLED)throw new IllegalStateException("L&D program is already cancelled");status=Status.CANCELLED;}
 public LdProgram successor(){if(status!=Status.APPROVED)throw new IllegalStateException("Only an APPROVED L&D program may be revised");LdProgram n=new LdProgram(getAgencyId(),planId,planVersion,planFingerprint,code,title,interventionVersionId,interventionFingerprint,evaluationFrameworkVersionId,evaluationFingerprint,intendedOutcomes,deliveryStrategy,scheduleStart,scheduleEnd,estimatedHours,estimatedCost,fundingSource,accountableEmployeeId,accountableEmployeeNo,accountableName,accountableAppointmentId,accountableFingerprint);n.seriesId=seriesId;n.programVersion=programVersion+1;n.supersedesId=getId();return n;}
 private void apply(String c,String t,String o,String d,LocalDate s,LocalDate e,BigDecimal h,BigDecimal cost,String f){code=requiredText(c,"code");normalizedCode=code.toUpperCase(java.util.Locale.ROOT);title=requiredText(t,"title");intendedOutcomes=requiredText(o,"intendedOutcomes");deliveryStrategy=requiredText(d,"deliveryStrategy");if(s==null||e==null||e.isBefore(s))throw new IllegalArgumentException("Valid program schedule window is required");scheduleStart=s;scheduleEnd=e;if(h==null||h.signum()<=0)throw new IllegalArgumentException("estimatedHours must be positive");estimatedHours=h.setScale(2,RoundingMode.HALF_UP);if(cost==null||cost.signum()<0)throw new IllegalArgumentException("estimatedCost cannot be negative");estimatedCost=cost.setScale(2,RoundingMode.HALF_UP);fundingSource=requiredText(f,"fundingSource");}private void editable(){if(status!=Status.DRAFT)throw new IllegalStateException("Only a DRAFT L&D program may be changed");}private static Long positive(Long v,String n){if(v==null||v<1)throw new IllegalArgumentException(n+" is required");return v;}
 public String getSeriesId(){return seriesId;}public int getProgramVersion(){return programVersion;}public String getSupersedesId(){return supersedesId;}public String getPlanId(){return planId;}public int getPlanVersion(){return planVersion;}public String getPlanFingerprint(){return planFingerprint;}public String getCode(){return code;}public String getNormalizedCode(){return normalizedCode;}public String getTitle(){return title;}public String getInterventionVersionId(){return interventionVersionId;}public String getInterventionFingerprint(){return interventionFingerprint;}public String getEvaluationFrameworkVersionId(){return evaluationFrameworkVersionId;}public String getEvaluationFingerprint(){return evaluationFingerprint;}public String getIntendedOutcomes(){return intendedOutcomes;}public String getDeliveryStrategy(){return deliveryStrategy;}public LocalDate getScheduleStart(){return scheduleStart;}public LocalDate getScheduleEnd(){return scheduleEnd;}public BigDecimal getEstimatedHours(){return estimatedHours;}public BigDecimal getEstimatedCost(){return estimatedCost;}public String getFundingSource(){return fundingSource;}public Long getAccountableEmployeeId(){return accountableEmployeeId;}public String getAccountableEmployeeNo(){return accountableEmployeeNo;}public String getAccountableName(){return accountableName;}public Long getAccountableAppointmentId(){return accountableAppointmentId;}public String getAccountableFingerprint(){return accountableFingerprint;}public Status getStatus(){return status;}public int getContentRevision(){return contentRevision;}public String getSubmittedBy(){return submittedBy;}public Instant getSubmittedAt(){return submittedAt;}public String getApprovedBy(){return approvedBy;}public Instant getApprovedAt(){return approvedAt;}
}
